import errno
import select
import socket
from abc import abstractmethod, ABCMeta
from time import sleep
from typing import Type

from six import add_metaclass

from .commons import LOGGER
from .exceptions import ConnectionTimedOut, InvalidHost, ConnectionFailed


@add_metaclass(ABCMeta)
class ConnectionClient(object):
    def __init__(self, host, port):
        self.host = host
        self.port = port

    @abstractmethod
    def send(self, *args):
        pass

    @abstractmethod
    def receive(self):
        pass

    @abstractmethod
    def close(self):
        pass


class TCPClient(ConnectionClient):
    def __init__(self, host, port):
        super(TCPClient, self).__init__(host, port)
        self._socket = self._prepare_socket()
        self._buffer_size = 2 ** 13

    def _prepare_socket(self, retries=3):  # noqa: C901
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        tries = 0
        connection_established = False

        while not connection_established:
            try:
                sock.connect((self.host, self.port))
                connection_established = True
            except socket.timeout:
                if tries < retries:
                    tries += 1
                else:
                    raise ConnectionTimedOut
            except socket.gaierror as e:
                raise InvalidHost(e)
            except socket.error as e:
                error_code = e.args[0]
                if error_code == errno.ECONNREFUSED:
                    LOGGER.error('taf.sbts.browser_server: Connection refused')
                raise ConnectionFailed(e)

        sock.setblocking(False)
        return sock

    def send(self, data):
        self._socket.sendall(data)

    def receive(self):  # noqa: C901
        # type () -> Union[bytearray, None]
        chunk = bytearray()
        try:
            rlist, wlist, xlist = select.select([self._socket], [], [])
            if rlist:
                chunk = self._socket.recv(self._buffer_size)
                if not chunk:
                    LOGGER.error('socket {} gracefully closed'.format(self._socket.fileno()))
                    return
        except socket.timeout:
            pass
        except socket.error as e:
            error_code = e.args[0]
            if error_code in (errno.EAGAIN, errno.EWOULDBLOCK):
                sleep(0.05)
                return
            elif error_code in (errno.EBADF,):
                LOGGER.debug('Caught "Bad file descriptor error"')
                sleep(1)
                return
            else:
                LOGGER.exception('socket error: {}'.format(repr(e)))
                return bytearray()
        else:
            return chunk

    def close(self):
        self._socket.shutdown(socket.SHUT_RDWR)
        self._socket.close()


def get_connection(host, port, client=TCPClient):
    # type: (str, int, Type[ConnectionClient]) -> ConnectionClient
    connection = client(host, port)
    LOGGER.info('taf.sbts.browser_server: successfully established connection to {}'.format((host, port)))
    return connection
